window.VO = [{"text": "The warden offers one hundred prisoners a deal.", "cap": "A deal for 100 prisoners", "dur": 2.287, "extra": 0.5, "file": "vo/00.wav"}, {"text": "Tomorrow, they'll stand in one long line, all facing forward, and each one gets a red or a blue hat.", "cap": "Red or blue hats", "dur": 5.726, "extra": 0.6, "file": "vo/01.wav"}, {"text": "Nobody can see their own hat. Only the hats of everyone in front of them.", "cap": "You only see the hats ahead", "dur": 4.033, "extra": 0.5, "file": "vo/02.wav"}, {"text": "Starting at the back, each prisoner says one word: red, or blue.", "cap": "Back to front: one word each", "dur": 3.458, "extra": 0.6, "file": "vo/03.wav"}, {"text": "Name your own hat color, and you walk free. Get it wrong, and you stay locked up.", "cap": "Right = free. Wrong = stay", "dur": 4.01, "extra": 0.6, "file": "vo/04.wav"}, {"text": "Everyone hears every answer, but no one can say anything else.", "cap": "No other talking", "dur": 3.566, "extra": 0.4, "file": "vo/05.wav"}, {"text": "Tonight, they can make a plan. How many can they save for sure?", "cap": "How many can they save?", "dur": 3.059, "extra": 0.5, "file": "vo/06.wav"}, {"text": "What's your plan? Pause, and comment it below!", "cap": "Comment your plan!", "dur": 2.343, "extra": 9.2, "file": "vo/07.wav"}, {"text": "Here's the trick. The prisoner at the back counts the red hats in front of them.", "cap": "Back prisoner counts red hats", "dur": 3.753, "extra": 0.6, "file": "vo/08.wav"}, {"text": "If the number is even, they say blue. If it's odd, they say red.", "cap": "Even \u2192 BLUE \u00b7 Odd \u2192 RED", "dur": 3.398, "extra": 0.8, "file": "vo/09.wav"}, {"text": "For them, it's a coin flip. But now everyone else knows the code.", "cap": "Now everyone knows the code", "dur": 3.551, "extra": 0.5, "file": "vo/10.wav"}, {"text": "Let's try it with five prisoners.", "cap": "Try it with 5", "dur": 1.689, "extra": 0.6, "file": "vo/11.wav"}, {"text": "The back prisoner sees two red hats. Two is even, so they say: blue.", "cap": "2 reds = even \u2192 BLUE", "dur": 3.905, "extra": 0.7, "file": "vo/12.wav"}, {"text": "Their own hat is red, so they lose the coin flip. That's the price of the code.", "cap": "The back one gambles", "dur": 4.048, "extra": 0.5, "file": "vo/13.wav"}, {"text": "Next in line sees only one red hat. That's odd, but the code said even. So the missing red is on their own head. Red!", "cap": "1 is odd \u2260 even \u2192 RED", "dur": 7.076, "extra": 0.6, "file": "vo/14.wav"}, {"text": "From here, each prisoner adds the reds they've heard behind them to the reds they can see ahead.", "cap": "Reds heard + reds seen", "dur": 4.877, "extra": 0.5, "file": "vo/15.wav"}, {"text": "If even or odd matches the code, their hat is blue. If it doesn't, it's red.", "cap": "Match \u2192 BLUE \u00b7 No match \u2192 RED", "dur": 4.142, "extra": 0.6, "file": "vo/16.wav"}, {"text": "Blue. Red. Blue. Every one of them is right.", "cap": "All correct!", "dur": 2.456, "extra": 0.9, "file": "vo/17.wav"}, {"text": "With a hundred prisoners, it works exactly the same.", "cap": "Same for 100", "dur": 2.721, "extra": 1.4, "file": "vo/18.wav"}, {"text": "Ninety nine walk free, guaranteed. And the one at the back still has a fifty-fifty chance.", "cap": "99 free, guaranteed", "dur": 5.149, "extra": 1.4, "file": "vo/19.wav"}, {"text": "Would you volunteer to stand at the back? Follow for more puzzles!", "cap": "Follow for more puzzles", "dur": 3.355, "extra": 1.6, "file": "vo/20.wav"}];
